DROP TABLE IF EXISTS `eisbecher_scores`;

CREATE ALGORITHM=UNDEFINED DEFINER=`k320202_iceapp`@`%` SQL SECURITY INVOKER VIEW `eisbecher_scores`  AS WITH   `bewertete_checkins` as (select `checkins`.`nutzer_id` AS `nutzer_id`,`checkins`.`eisdiele_id` AS `eisdiele_id`,`checkins`.`geschmackbewertung` AS `geschmackbewertung`,`checkins`.`preisleistungsbewertung` AS `preisleistungsbewertung`,round(((0.7 * `checkins`.`geschmackbewertung`) + (0.3 * `checkins`.`preisleistungsbewertung`)),2) AS `score` from `checkins` where ((`checkins`.`typ` = 'Eisbecher') and (`checkins`.`geschmackbewertung` is not null) and (`checkins`.`preisleistungsbewertung` is not null))), `nutzer_scores` as (select `bewertete_checkins`.`eisdiele_id` AS `eisdiele_id`,`bewertete_checkins`.`nutzer_id` AS `nutzer_id`,count(0) AS `checkin_count`,avg(`bewertete_checkins`.`score`) AS `durchschnitt_score`,avg(`bewertete_checkins`.`geschmackbewertung`) AS `durchschnitt_geschmack`,avg(`bewertete_checkins`.`preisleistungsbewertung`) AS `durchschnitt_preisleistung` from `bewertete_checkins` group by `bewertete_checkins`.`eisdiele_id`,`bewertete_checkins`.`nutzer_id`), `gewichtete_scores` as (select `nutzer_scores`.`eisdiele_id` AS `eisdiele_id`,`nutzer_scores`.`nutzer_id` AS `nutzer_id`,sqrt(`nutzer_scores`.`checkin_count`) AS `gewicht`,(`nutzer_scores`.`durchschnitt_score` * sqrt(`nutzer_scores`.`checkin_count`)) AS `gewichteter_score`,(`nutzer_scores`.`durchschnitt_geschmack` * sqrt(`nutzer_scores`.`checkin_count`)) AS `gewichteter_geschmack`,(`nutzer_scores`.`durchschnitt_preisleistung` * sqrt(`nutzer_scores`.`checkin_count`)) AS `gewichteter_preisleistung` from `nutzer_scores`) select `g`.`eisdiele_id` AS `eisdiele_id`,round((sum(`g`.`gewichteter_score`) / nullif(sum(`g`.`gewicht`),0)),2) AS `finaler_eisbecher_score`,round((sum(`g`.`gewichteter_geschmack`) / nullif(sum(`g`.`gewicht`),0)),2) AS `avg_geschmack`,round((sum(`g`.`gewichteter_preisleistung`) / nullif(sum(`g`.`gewicht`),0)),2) AS `avg_preisleistung` from `gewichtete_scores` `g` group by `g`.`eisdiele_id`  ;

