res`.`checkin_count`)) AS `gewichteter_preisleistung`,(`nutzer_scores`.`durchschnitt_geschmack` * sqrt(`nutzer_scores`.`checkin_count`)) AS `gewichteter_geschmack`,(`nutzer_scores`.`durchschnitt_geschmacksfaktor` * sqrt(`nutzer_scores`.`checkin_count`)) AS `gewichteter_geschmacksfaktor` from `nutzer_scores`) select `g`.`eisdiele_id` AS `eisdiele_id`,round((sum(`g`.`gewichteter_score`) / nullif(sum(`g`.`gewicht`),0)),2) AS `finaler_kugel_score`,round((sum(`g`.`gewichteter_geschmack`) / nullif(sum(`g`.`gewicht`),0)),2) AS `avg_geschmack`,round((sum(`g`.`gewichteter_geschmacksfaktor`) / nullif(sum(`g`.`gewicht`),0)),2) AS `avg_geschmacksfaktor`,round((sum(`g`.`gewichteter_preisleistung`) / nullif(sum(`g`.`gewicht`),0)),2) AS `avg_preisleistung` from `gewichtete_scores` `g` group by `g`.`eisdiele_id`  ;

