(1304, 53, 293, '2026-05-26 15:27:25', 'Kugel', 5.0, 4.8, NULL, 4.2, 'Einfach total lecker. Sehr fruchtig, nicht zu süß und in der Unternote etwas nach Rosmarin. Super', NULL, 'Fahrrad', 1, NULL),
(1305, 156, 782, '2026-05-26 16:28:33', 'Kugel', 4.5, 4.5, NULL, 5.0, '', NULL, 'Auto', 0, NULL),
