(1367, 156, 356, '2026-06-05 16:28:05', 'Softeis', 5.0, NULL, NULL, 5.0, '', NULL, 'Zu Fuß', 0, NULL),
(1368, 1, 356, '2026-06-05 17:34:22', 'Softeis', 4.6, NULL, NULL, 4.0, 'Mango war sehr fruchtig und Schokolade ebenfalls sehr intensiv vom Geschmack, aber mehr nach dunklem Kakao als cremiger Schokolade. Wer mehr so der Zartbitter Typ ist, wird es mögen 👍🏼😊Beide Sorten waren vegan.', NULL, 'Fahrrad', 1, NULL),
