(1471, 62, 202, '2026-06-28 14:36:38', 'Softeis', 3.7, 3.6, NULL, 3.5, '', NULL, 'Auto', 0, NULL),
(1472, 1, 5, '2026-06-28 15:09:23', 'Kugel', 4.1, 4.4, NULL, 4.7, 'Heute gab\'s ziemlich große Kugeln in einer knusprigen Waffel.\r\nDas hab ich bei Rüllis auch schon schlechter erlebt 👍🏼😅\r\nDas Eis war ganz gut, aber nichts besonderes. Beide Sorten relativ fest und hätten cremiger sein können.', NULL, 'Fahrrad', 1, NULL),
