(1500, 3, 847, '2026-07-03 17:48:29', 'Eisbecher', 4.3, NULL, NULL, 3.8, 'Ein großer Eisbecher, der geschmacklich voll überzeugt hat! Schönes Eiskaffee in toller Lage!', NULL, 'Auto', 0, NULL),
(1501, 53, 849, '2026-07-04 11:55:08', 'Kugel', 4.4, NULL, NULL, 4.3, '', NULL, 'Auto', 1, 96),
(1502, 1, 850, '2026-07-04 15:28:11', 'Eisbecher', 1.3, NULL, NULL, 2.3, 'Auf dem Weg in den Urlaub mal einen Eis-Stopp gemacht.\r\nVanilleeis war schon aus, deshalb gab\'s den Eiskaffee mit Schoko-Eis.\r\nDas Eis bestand leider zu 90% aus Eiskristallen und der Kaffee hat auch nicht geschmeckt 😶‍🌫️', NULL, 'Auto', 1, 97),
(1503, 53, 852, '2026-07-04 18:58:39', 'Kugel', 5.0, 5.0, NULL, 5.0, 'Sehr lecker, ich würde fast sagen mein bestes Pistazien Eis ever', NULL, 'Fahrrad', 1, NULL),
