(405, 1, 1654, NULL, 'Da hast du ja heute eine krasse Eis Tour mit dem Rad hingelegt 💪🏼 sehr cooles Ding! 🥳', '2026-07-26 17:13:07', NULL, NULL, NULL),
(406, 235, 1654, NULL, 'Danke, 155km für die Sommereis-Challenge🔥', '2026-07-26 18:16:48', NULL, NULL, NULL),
(407, 1, NULL, NULL, 'Wahnsinn! 💪🏼😍\nSuper cool, wie du die App belebst 💯🔥', '2026-07-28 13:46:20', NULL, NULL, 3630),
(408, 1, 1660, NULL, 'Einen schönen Urlaub! 🏖️', '2026-07-28 13:48:56', NULL, NULL, NULL),
(410, 31, 1660, NULL, 'Danke', '2026-07-29 06:03:59', NULL, NULL, NULL),
(411, 1, 1666, NULL, '🤘🏼🤘🏼🤘🏼WAAAAACKEN 🤘🏼🤘🏼🤘🏼', '2026-07-30 07:48:03', NULL, NULL, NULL),
(412, 1, 1680, NULL, 'Krasse Waffel für eine Kugel Eis 🥺😅\nUnd wieder mal gute Preise nach Frankreich 😅🤩', '2026-08-01 08:58:55', NULL, NULL, NULL),
(413, 1, 1686, NULL, 'Und auch noch sehr günstig für Chemnitzer Innenstadt 👌🏼\nMuss ich auch mal wieder hin 😁', '2026-08-03 15:43:05', NULL, NULL, NULL),
(414, 1, NULL, NULL, 'Herzlich Willkommen auf der Ice-App 😎\nAuf viele köstliche Eis-Abenteuer! 🤘🏼🍨', '2026-08-07 12:02:36', NULL, 322, NULL),
(415, 1, NULL, NULL, 'Herzlich Willkommen auf der Ice-App 😎\nAuf viele köstliche Eis-Abenteuer! 🤘🏼🍨', '2026-08-07 18:29:04', NULL, 323, NULL),
(416, 1, 1711, NULL, 'Klingt äußerst interessant und schmackhaft 😍😏', '2026-08-09 12:52:34', NULL, NULL, NULL),
(417, 156, 1713, NULL, '🫠🙌 Isso', '2026-08-09 13:33:51', NULL, NULL, NULL),
(418, 1, 1715, NULL, 'Uhh eine meiner Lieblingseisdielen in Chemnitz 👌🏼😊', '2026-08-09 14:49:08', NULL, NULL, NULL),
(419, 322, 1715, NULL, 'Heute das erstmal dort gehalten und ich war positiv überrascht!', '2026-08-09 15:17:52', NULL, NULL, NULL),
(420, 1, 1715, NULL, 'ja ging mir das erste mal auch so. Aber super freundlich, geile große Portionen, ne leckere Waffel und für Chemnitz echt sehr faire Preise 🙌', '2026-08-09 15:50:25', NULL, NULL, NULL),
(421, 1, 1713, NULL, 'Das ist wirklich unnötig, da denkt man 2026 sollte sowas schon lange nicht mehr existieren, aber nein gibt\'s halt doch leider noch 🫣🙄', '2026-08-09 16:03:58', NULL, NULL, NULL),
(422, 1, 1719, NULL, 'Das sieht ja edel aus, könnte auch direkt so in einer Speisekarte abgedruckt werden 😏😍👌🏼', '2026-08-10 12:45:18', NULL, NULL, NULL),
(423, 1, 1737, NULL, 'Herzlich Willkommen auf der Ice-App ✌🏼☺️ \nCool dass du hier bist und auf viele weitere köstliche Eis-Abenteuer 🍦', '2026-08-15 18:27:31', NULL, NULL, NULL),
(424, 322, 1746, NULL, 'Leider den QR-Code für die Sommer-Sammelaktion nicht gesehen, da auch sehr viele Leute angestanden haben.', '2026-08-16 17:17:52', NULL, NULL, NULL),
(425, 1, 1746, NULL, 'Gut dass du es erwähnst, ich hab dir den passenden Award so vergeben 😉', '2026-08-16 19:20:55', NULL, NULL, NULL),
(426, 1, NULL, 739, 'das sind ja mal Preise! 😍', '2026-08-23 15:43:47', NULL, NULL, NULL),
(427, 125, NULL, NULL, 'Ein Hoch auf das kosmische Kugelglück! 🍨😂\nUr-Essenz des Eises - was für ein Wahnsinns-Meilenstein! 🙌🥳', '2026-08-30 16:33:44', NULL, NULL, 3854),
(428, 1, NULL, NULL, 'Haha, vielen Dank @Suklaafani  ☺️ \nHerzlichen Glückwunsch zum ersten Jubiläum auf der Ice-App, ein siebentel meiner Check-ins hast du ja auch schon an Kugeln gesammelt 😎👌🏼', '2026-08-30 17:44:38', NULL, NULL, 3854),
(429, 1, 1805, NULL, 'Nach einer 100km Radtour ist das eine mehr als verdiente Belohnung 👌🏼😋😋', '2026-09-01 17:39:51', NULL, NULL, NULL),
(430, 125, NULL, NULL, 'Danke!🥳 Ich geb alles 😄', '2026-09-01 18:00:20', NULL, NULL, 3854),
(432, 1, 1844, NULL, 'Gratulation zum Abschluss deiner ersten Challenge 🎊🔥', '2026-09-16 05:40:39', NULL, NULL, NULL);
