INSERT INTO `photo_challenges` (`id`, `title`, `description`, `status`, `group_size`, `start_at`, `min_image_created_at`, `submission_deadline`, `submission_limit_per_user`, `allow_direct_uploads`, `is_country_challenge`, `reveal_countries_at_ko`, `group_schedule`, `group_advancers`, `lucky_loser_slots`, `ko_bracket_size`, `created_by`, `created_at`, `updated_at`) VALUES
(3, 'Ice-App Fotochallenge – 1 Jahr Ice-App!', 'Ein Jahr voller Eis-Momente liegt hinter uns – jetzt suchen wir die besten Eisfotos aus der Ice-App! 🎉\r\n\r\nWähle einfach deine schönsten Bilder aus deinen bisherigen Ice-App Posts aus und reiche sie für die Challenge ein. Egal ob perfekte Kugel, beeindruckender Eisbecher oder dein Lieblingsmoment mit Eis. 🍨\r\n\r\n🏆 Es wird tolle Preise zu gewinnen geben! Auch wer nur abstimmt hat eine Chance zu gewinnen.\r\n\r\nAlso stöbere durch deine bisherigen Beiträge, reiche deine Favoriten ein und lade Freunde ein, ebenfalls mitzumachen.\r\n\r\nViel Spaß bei der Fotochallenge! 📷🍦', 'finished', 4, '2026-03-06 09:00:00', NULL, '2026-03-14 12:00:00', 3, 0, 0, 0, NULL, 2, 2, NULL, 1, '2026-03-06 08:30:41', '2026-05-10 19:15:31'),
(4, 'Sport & Eis', 'Anlässlich der Ice-Tour 2026 suchen wir die coolsten Bilder rund um Sport und Eis!\nEgal ob Rennrad, MTB, Motorrad, Laufschuhe oder sogar Ski – Hauptsache Bewegung und irgendwo darf natürlich ein Eis nicht fehlen 😄\n\nZeig uns:\n📸 deine Eis-Pause nach dem Training\n📸 den legendären Eisdielen-Stop mitten auf der Tour\n📸 dein Bike + Eis vor schöner Kulisse\n📸 oder einfach die perfekte Kombination aus Sport und Genuss\n\nDenn mal ehrlich:\nKalorien zählen nicht, wenn man sie sich vorher verdient hat 🍨🔥\n\nLade jetzt dein Bild hoch und sichere dir die Chance auf den nächsten legendären Ice-App Foto-Challenge Sieg! 🏆', 'finished', 4, NULL, NULL, '2026-05-31 23:00:00', 5, 1, 0, 0, '[{\"start_at\":\"2026-06-01 18:59:00\",\"duration_days\":14,\"groups\":5}]', 2, 0, NULL, 1, '2026-05-14 08:22:31', '2026-08-09 18:06:07'),
(5, 'Eis - Weltmeisterschaft 2026', 'Passend zur Fußball WM, suchen wir das beste Eis (Bild) der Welt!\nAus 27 verschiedenen Ländern wurde je ein Bild ausgesucht, welches in das Turnier geschickt wird.\n\nAb den KO Phasen seht ihr dann auch, für welches Land ihr votet.\nIn der Gruppenphase ist es noch geheim :D', 'finished', 3, '2026-06-01 09:00:00', NULL, '2026-06-09 23:59:00', 3, 0, 1, 1, '[{\"start_at\":\"2026-06-11 09:00:00\",\"duration_days\":7,\"groups\":3},{\"start_at\":\"2026-06-18 09:00:00\",\"duration_days\":7,\"groups\":3},{\"start_at\":\"2026-06-25 09:00:00\",\"duration_days\":7,\"groups\":3}]', 1, 7, 16, 1, '2026-06-01 15:55:29', '2026-08-09 18:08:40');
