INSERT INTO `routen` (`id`, `eisdiele_id`, `nutzer_id`, `url`, `komoot_share_token`, `embed_code`, `name`, `beschreibung`, `typ`, `laenge_km`, `hoehenmeter`, `schwierigkeit`, `ist_oeffentlich`, `erstellt_am`) VALUES
(1, 7, 1, 'https://www.komoot.com/de-de/tour/766051588/', 'a0wppn9FtkukVMb4eIO1LH0uC3zs4nkuulEG5yYiADhc9g47xq', '<iframe src=\"https://www.komoot.com/de-de/tour/766051588/embed?share_token=a0wppn9FtkukVMb4eIO1LH0uC3zs4nkuulEG5yYiADhc9g47xq\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Steinberg, Kuhberg und Eibenstock', 'Traumhafte Runde durchs Vogtland / westliche Erzgebirge auf sehr ruhigen Straßen, tollen Bergen und einem schönen Eis-Stopp in Eibenstock.', 'Rennrad', 132.00, 1630, 'Schwer', 1, '2025-05-06 18:51:58'),
(2, 12, 1, 'https://www.komoot.com/de-de/tour/2095130840/', 'ap4vnyKtDa4kQ7cUIHWHjzRuQ4EE4wcnWfh4SX7SzDwcpGnhFF', '<iframe src=\"https://www.komoot.com/de-de/tour/2095130840/embed?share_token=ap4vnyKtDa4kQ7cUIHWHjzRuQ4EE4wcnWfh4SX7SzDwcpGnhFF\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Hübschmann\'s Eislädl ', '', 'Rennrad', 87.50, 1420, 'Schwer', 1, '2025-05-06 18:51:58'),
(3, 23, 1, 'https://www.komoot.de/tour/2280368377/', 'a3mG8iRmcYbY1045GvIhcZ6Ch1qaei3Q8zZfHTqWPoGqmzN8PB', '<iframe src=\"https://www.komoot.com/de-de/tour/2280368377/embed?share_token=a3mG8iRmcYbY1045GvIhcZ6Ch1qaei3Q8zZfHTqWPoGqmzN8PB\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Albrecht Eis bei Nossen und Softeis in Hartha ', '', 'Rennrad', 134.00, 1310, 'Schwer', 1, '2025-05-06 18:51:58'),
(4, 24, 1, 'https://www.komoot.com/de-de/tour/2105973916/', 'aaPFk4zNdiuVWi0ZnbkJWSoLFS7NSN5CbtGIlU53lvLlZlAKxr', '<iframe src=\"https://www.komoot.com/de-de/tour/2105973916/embed?share_token=aaPFk4zNdiuVWi0ZnbkJWSoLFS7NSN5CbtGIlU53lvLlZlAKxr\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Zum Torteneck Olbernhau', 'Los gehts durchs Zschopautal mit relativ gemütlicher Steigung bis hoch zum Erzgebirgskamm, den geht es dann auf ruhigen Wegen durch den Wald und kleinere Dörfer entlang bis nach Olbernhau, wo dann das Torteneck auf einen wartet. Von da aus geht es wellig zurück nach Chemnitz.', 'Rennrad', 123.00, 1660, 'Schwer', 1, '2025-05-06 18:51:58'),
(5, 30, 1, 'https://www.komoot.com/de-de/tour/2116969975/', 'aOjrIbBFZ0G6Oev1Ajn3sK3L9t4nTo03R9LbBZIM4y6ZriPKr6', '<iframe src=\"https://www.komoot.com/de-de/tour/2116969975/embed?share_token=aOjrIbBFZ0G6Oev1Ajn3sK3L9t4nTo03R9LbBZIM4y6ZriPKr6\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', '', '', 'Rennrad', 115.00, 1810, 'Schwer', 1, '2025-05-06 18:51:58'),
(6, 31, 1, 'https://www.komoot.com/de-de/tour/2109432795/', 'atw46aGE8ustrenEcMyr6X5NVCQviCSV71gB86FHE3JApl36UC', '<iframe src=\"https://www.komoot.com/de-de/tour/2109432795/embed?share_token=atw46aGE8ustrenEcMyr6X5NVCQviCSV71gB86FHE3JApl36UC\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', '', '', 'Rennrad', 133.00, 860, 'Mittel', 1, '2025-05-06 18:51:58'),
(9, 46, 1, 'https://www.komoot.com/de-de/tour/2117187697/', 'aV2Hu3UCsgD69l3EKo2M5GZWarrQeZxDItCxpA9N2l1M52Kd4N', '<iframe src=\"https://www.komoot.com/de-de/tour/2117187697/embed?share_token=aV2Hu3UCsgD69l3EKo2M5GZWarrQeZxDItCxpA9N2l1M52Kd4N\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Eiscafé Eiswürfel', '', 'Rennrad', 115.00, 1560, 'Schwer', 1, '2025-05-06 18:51:58'),
(12, 74, 1, 'https://www.komoot.com/de-de/tour/2143692597/', 'anzEZqQDeHTcRq1YJOXRuRMoVfkIrs1Chfik2ID3iNgsVjSQTj', '<iframe src=\"https://www.komoot.com/de-de/tour/2143692597/embed?share_token=anzEZqQDeHTcRq1YJOXRuRMoVfkIrs1Chfik2ID3iNgsVjSQTj&profile=1\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Zum Café Flora', '', 'Rennrad', 124.00, 1850, 'Schwer', 1, '2025-05-06 18:51:58'),
(13, 89, 1, 'https://www.komoot.com/de-de/tour/1259315746/', 'aAcrsdK0p1Ho74xaV4g7PsGmD375xR3P76dPBRUJKFFftZc1hi', '<iframe src=\"https://www.komoot.com/de-de/tour/1259315746/embed?share_token=aAcrsdK0p1Ho74xaV4g7PsGmD375xR3P76dPBRUJKFFftZc1hi&profile=1\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Einmal um die Talsperre Pöhl herum', '', 'Rennrad', 172.00, 1980, 'Schwer', 1, '2025-05-06 18:51:58'),
(14, 98, 1, 'https://www.komoot.com/de-de/tour/2156485682/', 'aXul3Yn3HECtwMmDcRcbEHHOe6wXSdzb6D4XK1r4QNn7shP3GH', '<iframe src=\"https://www.komoot.com/de-de/tour/2156485682/embed?share_token=aXul3Yn3HECtwMmDcRcbEHHOe6wXSdzb6D4XK1r4QNn7shP3GH&profile=1\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Eisbär Planitz', '', 'Rennrad', 109.00, 1100, 'Schwer', 1, '2025-05-06 18:51:58'),
(15, 101, 1, 'https://www.komoot.com/de-de/tour/2159077294/', 'aIGChRNihGNZKPZKdliYH3gg0Rt7MDGqwzTs9WukJK7TG71j7M', '<iframe src=\"https://www.komoot.com/de-de/tour/2159077294/embed?share_token=aIGChRNihGNZKPZKdliYH3gg0Rt7MDGqwzTs9WukJK7TG71j7M\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Albrecht Eiseck Nossen', 'Auf dem Hinweg geht es etwas bergig über Freiberg nach Nossen. Dort kann man sich für wenig Geld sehr viel super leckeres Eis gönnen bevor es dann etwas flacher zurück nach Chemnitz geht.', 'Rennrad', 135.00, 1510, 'Schwer', 1, '2025-05-06 18:51:58'),
(16, 106, 1, 'https://www.komoot.com/de-de/tour/2201870273/', 'aYhNWuNhx23QiYtyROzDU7xXLieCNQNDS1hfjXJwSWjw8yW9nd', '<iframe src=\"https://www.komoot.com/de-de/tour/2201870273/embed?share_token=aYhNWuNhx23QiYtyROzDU7xXLieCNQNDS1hfjXJwSWjw8yW9nd\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Höhenmeter in Kombination mit Eis ', 'Eine ordentlich anspruchsvolle Runde durchs Gebirge. Nach dem es im Zschopau Tal relativ gleichmäßig bergauf geht, geht\'s dann steil nach Jöhstadt wo mit dem Eiscafé Bartsch eine gute Quelle für Softeis wartet.\nDanach wird es richtig bergig, von hinten wird sich den Auersberg genähert, der natürlich auch erklommen wird, wenn man einmal da ist.\n\nDanach gibt\'s feinstes Eis bei der Eismanufaktur Lipp in Annaberg, aber Obacht, danach warten auch noch einige giftige, steile Rampen.\nIn Summe ein wahres Höhenmeter Fest mit leckerstem Eis 😍🍦', 'Rennrad', 108.00, 1900, 'Schwer', 1, '2025-05-06 18:51:58'),
(34, 46, 1, 'https://www.komoot.com/de-de/tour/2223149396/', 'aPnSArnRnwsrHdGtf8RisNJrJdYn2qdInbmHITiAZ3Gtswe0A2', '<iframe src=\"https://www.komoot.com/de-de/tour/2223149396/embed?share_token=aPnSArnRnwsrHdGtf8RisNJrJdYn2qdInbmHITiAZ3Gtswe0A2\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Wanderung rund um Eiscafé Eiswürfel ', 'Die Wanderung habe ich noch geplant. Sobald sie gemacht wurde, werde ich berichten.', 'Wanderung', 7.50, 200, 'Leicht', 1, '2025-05-07 08:41:59'),
(48, 149, 1, 'https://www.komoot.com/de-de/tour/2225043577/', 'axZv8tPoWNnuly4DGuTKzmSl0TkblxCD9p9RWeoFKOlHMLtkLl', '<iframe src=\"https://www.komoot.com/de-de/tour/2225043577/embed?share_token=axZv8tPoWNnuly4DGuTKzmSl0TkblxCD9p9RWeoFKOlHMLtkLl\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'von Chemnitz zum Eis-Karli in Rodewisch', 'Möchte ich noch fahren.', 'Rennrad', 133.00, 1800, 'Schwer', 0, '2025-05-08 04:08:58'),
(49, 150, 1, 'https://www.komoot.com/de-de/tour/2225276682/', 'a5yq8SrIGOjf71VeGkuGzcpqD4WORqZ805eF6DwAfJF6OOQ7Qj', '<iframe src=\"https://www.komoot.com/de-de/tour/2225276682/embed?share_token=a5yq8SrIGOjf71VeGkuGzcpqD4WORqZ805eF6DwAfJF6OOQ7Qj\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Göltzschtalbrücke', '', 'Rennrad', 144.00, 1430, 'Schwer', 1, '2025-05-08 07:03:25'),
(64, 9, 1, 'https://www.komoot.com/de-de/tour/2260332775/', 'aGiI6OPvnX7PSTiwdPihquVe8zeOFjRgvuyGaLiyKKdHwgJ4lR', '<iframe src=\"https://www.komoot.com/de-de/tour/2260332775/embed?share_token=aGiI6OPvnX7PSTiwdPihquVe8zeOFjRgvuyGaLiyKKdHwgJ4lR\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Über Kohlebahnradweg zur Eisdiele Dietz', 'Schöne, einfache Rennrad Runde: über Klaffenbach geht es raus aus Chemnitz, den Kohlebahnradweg entlang bis nach Lugau. Von dort rollt man quasi komplett Gersdorf herunter bis am Ende vom Ort die Eisdiele Dietz einen erwartet.\nDort kann man lecker Eis essen bevor es über Oberlungwitz und Mittelbach zurück nach Chemnitz geht.', 'Rennrad', 35.10, 230, 'Leicht', 1, '2025-05-21 19:30:15'),
(66, 56, 1, 'https://www.komoot.com/de-de/tour/2273621482/', 'aj4XMWv3aKQrZhaNWTDN23cqn2CWpEMrviLECx99Fr6yqMR1NV', '<iframe src=\"https://www.komoot.com/de-de/tour/2273621482/embed?share_token=aj4XMWv3aKQrZhaNWTDN23cqn2CWpEMrviLECx99Fr6yqMR1NV\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Von Chemnitz zum Schloss-Café Ponitz', 'Das Schloss-Café Ponitz wurde mit empfohlen, mal schauen was es taugt. Ich hab mal eine bisschen flachere Runde über Norden geplant.', 'Rennrad', 105.00, 890, 'Mittel', 1, '2025-05-27 05:54:21'),
(67, 4, 1, 'https://www.komoot.de/tour/2104351326/', 'aHT51hSqmzvoimJE1ECm1hf7qqwacEh0aalXN3oG498PaVMQ39', '<iframe src=\"https://www.komoot.com/de-de/tour/2104351326/embed?share_token=aHT51hSqmzvoimJE1ECm1hf7qqwacEh0aalXN3oG498PaVMQ39\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Softeis in Harthau', 'Eine Runde - 3 neue Eisdielen für mich erkunden.', 'Rennrad', 118.00, 1130, 'Mittel', 1, '2025-05-29 03:02:35'),
(68, 21, 1, 'https://www.komoot.de/tour/2283324311/', 'aUCCsXVk38ybSKkm18RKUb5pqazdmISD7gR68bcPrKS0fQ9v5o', '<iframe src=\"https://www.komoot.com/de-de/tour/2283324311/embed?share_token=aUCCsXVk38ybSKkm18RKUb5pqazdmISD7gR68bcPrKS0fQ9v5o\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Von Chemnitz über Klaffenbach zum Eiscafé \'kleine Verführung\'', '', 'Gravel', 38.60, 360, 'Leicht', 1, '2025-05-30 14:35:30'),
(69, 213, 1, 'https://www.komoot.com/de-de/tour/2333240505/', 'a8wDrc25tT2lmpM0QFeOX7dyQ4SUneSM5Uy9Yv0vlN3nYP6Kcl', '<iframe src=\"https://www.komoot.com/de-de/tour/2333240505/embed?share_token=a8wDrc25tT2lmpM0QFeOX7dyQ4SUneSM5Uy9Yv0vlN3nYP6Kcl\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Von Chemnitz zur Bäckerei Steffi Reichardt in Löbichau', '', 'Rennrad', 135.00, 1440, 'Schwer', 1, '2025-06-18 05:01:26'),
(70, 22, 1, 'https://www.komoot.de/tour/2422400323/', 'a67QorxOC0qKPzFOAfxbGGjhG71wR8Euobw1zPNkRekU8ABIpO', '<iframe src=\"https://www.komoot.com/de-de/tour/2422400323/embed?share_token=a67QorxOC0qKPzFOAfxbGGjhG71wR8Euobw1zPNkRekU8ABIpO\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Im Chemnitztal zum Eiscafé Elisenhof ', 'Der relativ schnellste aber auch schön ruhiger Weg mit dem Rennrad von Chemnitz zum Eiscafé Elisenhof in Kohren-Salis.', 'Rennrad', 88.20, 690, 'Mittel', 1, '2025-07-21 01:32:38'),
(72, 60, 1, 'https://www.komoot.de/tour/2422400323/', 'a67QorxOC0qKPzFOAfxbGGjhG71wR8Euobw1zPNkRekU8ABIpO', '<iframe src=\"https://www.komoot.com/de-de/tour/2422400323/embed?share_token=a67QorxOC0qKPzFOAfxbGGjhG71wR8Euobw1zPNkRekU8ABIpO\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Späte Feierabendrunde', 'Die Eisdiele in Limbach Oberfrohna hat bis 19 Uhr auf, damit kann man auch noch Recht spät starten und bekommt immer noch ein Eis. 🍦👍🏼', 'Rennrad', 76.50, 740, 'Mittel', 1, '2025-07-23 18:04:57'),
(73, 93, 1, 'https://www.komoot.com/de-de/tour/2512610805/', 'aDT7DrgAUNeZI1Tkga8w4fPqWPad58xs0Lod627WFdiMigeQQZ', '<iframe src=\"https://www.komoot.com/de-de/tour/2512610805/embed?share_token=aDT7DrgAUNeZI1Tkga8w4fPqWPad58xs0Lod627WFdiMigeQQZ\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Freiberg -> Nossen -> Döbeln', '', 'Rennrad', 132.00, 1530, 'Schwer', 0, '2025-07-28 12:13:27'),
(74, 114, 1, 'https://www.komoot.de/tour/2443810417/', 'a6TwsdM3xAAgtFQ9leCnXFMn4fYsLwgZ57sXR3wiIp7YMo4KAv', '<iframe src=\"https://www.komoot.com/de-de/tour/2443810417/embed?share_token=a6TwsdM3xAAgtFQ9leCnXFMn4fYsLwgZ57sXR3wiIp7YMo4KAv\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Cycle the Unseen 200 - mit Eisstopps ', 'Für alle Starter des 200km Brevets gibt\'s hier die Route erweitert mit einigen Eis-Stopps die direkt auf der Strecke liegen oder nur einen minimalen Umweg bedeuten.\n\nDie ersten Eisdielen passiert man wenn sie noch geschlossen sind, los geht es mit \n- Kilometer 94: Bäckerei Bräunig in Ehrenfriedersdorf \n- Kilometer 134: n\'Eis zapfen in Frankenberg\n- Kilometer 158: Eiscafé Venezia in Mittweida (alternativ gibt es noch 2-3 andere Eis Möglichkeiten in Mittweida)\n- Kilometer 176: Eiscafé Krause Wechselburg\n- Im Ziel: Ice-Eis Pinguin oder Karl mags Süß ', 'Rennrad', 204.00, 2540, 'Schwer', 1, '2025-08-02 00:08:33'),
(75, 57, 1, 'https://www.komoot.com/de-de/tour/2468788191/', 'aWHQ9Nx09zfvEePJlP5kzFYZYHGynqjmRwNLSMtHCpg7j4yh6R', '<iframe src=\"https://www.komoot.com/de-de/tour/2468788191/embed?share_token=aWHQ9Nx09zfvEePJlP5kzFYZYHGynqjmRwNLSMtHCpg7j4yh6R\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Konditorei Seifert & Eisfabrik Gößnitz', 'Aus ursprünglich 3 geplanten Eis Stopps wurde es doch nur ein Stopp bei dem es Kuchen gab und ein Softeis-Stopp bei der Eisfabrik Gößnitz', 'Rennrad', 120.00, 900, 'Mittel', 1, '2025-08-06 05:32:17'),
(77, 105, 1, 'https://www.komoot.com/de-de/tour/2680028926/', 'a9h4TkeviZYDE8J7vuRT8nTJ9wA3kc1A90qCGDQ3uNVdtZgWWJ', '<iframe src=\"https://www.komoot.com/de-de/tour/2680028926/embed?share_token=a9h4TkeviZYDE8J7vuRT8nTJ9wA3kc1A90qCGDQ3uNVdtZgWWJ\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Montags geöffnete Eisdielen Erzgebirge', 'Eine ziemlich schwere Tour durchs Erzgebirge. Mit vielen Höhenmetern und einigen Einkehrmöglichkeiten, das Besondere: die Eisdielen haben Montags geöffnet (was bei vielen Eisdielen ja oft der Ruhetag ist)\n\nnach 51,6 km: Landbäckerei BurgBlick\nnach 63,6 km: Café Eisbär\nnach 69,4 km: Eisdiele & Café Nestler\nnach 84,0 km: Philipps Eisdielerei', 'Rennrad', 130.00, 2070, 'Schwer', 1, '2025-09-02 08:33:10'),
(78, 21, 53, 'https://www.komoot.de/tour/2663531081/', 'a9GKZKzctq5zs9niXyZNU1Z9RsuJeqDHnPz14ui18GjRznzpGK', '<iframe src=\"https://www.komoot.com/de-de/tour/2663531081/embed?share_token=a9GKZKzctq5zs9niXyZNU1Z9RsuJeqDHnPz14ui18GjRznzpGK\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', '3 Eisdielen Tour', 'Schöne MTB Tour mit paar kleinen Trails', 'MTB', 28.00, 300, 'Mittel', 1, '2025-11-01 21:44:35'),
(85, 440, 1, 'https://www.komoot.de/tour/2723473538/', 'ayXDvtZO1tvCOFqOtBekIEe7qIXa2VrLW9DVoPrcbJDFpIq0e9', '<iframe src=\"https://www.komoot.com/de-de/tour/2723473538/embed?share_token=ayXDvtZO1tvCOFqOtBekIEe7qIXa2VrLW9DVoPrcbJDFpIq0e9\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Eisdiele Wermsdorf ', 'Nächsten Sommer muss ich doch mal die Eisdiele testen, die IceGoe gefunden hat.', 'Rennrad', 129.00, 1200, 'Schwer', 1, '2025-12-22 04:08:12'),
(86, 584, 1, 'https://www.strava.com/routes/3448968983664998364/', NULL, NULL, 'Zum Holzcafé', '', 'Rennrad', 100.00, 1000, 'Mittel', 0, '2026-01-21 08:39:44'),
(87, 101, 1, 'https://www.komoot.com/de-de/tour/2764473108/', 'ans65F5gJktJQjoGqPaONHHBwUAg5AW1354ipWTe3NsFCt8Y3W', '<iframe src=\"https://www.komoot.com/de-de/tour/2764473108/embed?share_token=ans65F5gJktJQjoGqPaONHHBwUAg5AW1354ipWTe3NsFCt8Y3W\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Martina Kodym Testfahrt', '', 'Rennrad', 120.00, 1460, 'Schwer', 1, '2026-01-27 09:46:31'),
(89, 165, 53, 'https://www.komoot.com/de-de/tour/2786101566/', 'aGQ6Cuqa82iup9o3iu5LiVaXNGA4d0ctFa7NxVjLuDYD6uCAXa', '<iframe src=\"https://www.komoot.com/de-de/tour/2786101566/embed?share_token=aGQ6Cuqa82iup9o3iu5LiVaXNGA4d0ctFa7NxVjLuDYD6uCAXa\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', '3Eisdielen im Westen von Chemnitz', 'Kleine Runde mit schönen Sehenswürdigkeiten ', 'Gravel', 16.00, 160, 'Leicht', 1, '2026-02-15 16:13:50'),
(90, 10, 19, 'https://www.komoot.de/tour/2787906672/', 'ahzkLO9YtMAvdICX8D5fUtvzCefTTyX59i0Gb2ye0M7X4eIi16', '<iframe src=\"https://www.komoot.com/de-de/tour/2787906672/embed?share_token=ahzkLO9YtMAvdICX8D5fUtvzCefTTyX59i0Gb2ye0M7X4eIi16\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Von Hohenstein-Er. nach Kuhschnappel  und zurück ', 'Vom Altmarkt Hohenstein-Ernstthal, auf welchem gleich zwei Eisdielen besucht werden können, führt die Tour zunächst durch die Stadt, später durch den Hainholzwald und den Rüßdorfer Wald nach Kuhschnappel zum Ziegenhof Winter. Die Tour ist als Hin- und Rückweg gedacht und kann natürlich an beiden Endpunkten gestartet werden. \nBitte beachtet, dass manche Eisdielen auf der Route saisonale Öffnungszeiten haben.', 'Wanderung', 11.00, 180, 'Mittel', 1, '2026-02-17 07:29:58'),
(92, 428, 1, 'https://www.komoot.com/de-de/tour/2850410998/', 'aUkEt3TYvmJo3NNkVmN3JQ1T3JNnZBLGEXE1abcDfLL08X6JjT', '<iframe src=\"https://www.komoot.com/de-de/tour/2850410998/embed?share_token=aUkEt3TYvmJo3NNkVmN3JQ1T3JNnZBLGEXE1abcDfLL08X6JjT\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Laaaange Fahrt mit Viiiiieeel Eiscreme!', 'Heute ist es leicht eskaliert, deutlich mehr Kilometer und Eisdielen als ursprünglich geplant.\nSehr abwechslungsreiche Eis Erlebnisse entlang der Strecke.\nBeginnend mit sehr großen, super luftigen Kugeln vom Bäcker, über eine leider geschlossene Eisdiele in Wermsdorf. Dort gab es aber noch das Café am Schloss, welches leckere Waffeln und interessante Sorten hatte.\nIn Oschatz gabs bei Eiscafé Amore ein Heidelbeereis auf dem Markt.\nHighlight war definitv Eiscafé Rialto in Döbeln, suuper leckere Sorten, große Kugeln, leckere Waffel und alles selber hergestellt mit super vielen Keks, Schokostückchen und absolut cremig toller Konsistenz. Dazu noch ein super sympathischer Betreiber.\nAm Ende gab\'s bei Friedel\'s Cafe noch mal komplettes Kontrastprogramm. Ein \'Kremeeis\', welches aus Milch, Ei und Zucker hergestellt wird. Deutlich fester von der konsistent und auf jeden Fall mal was besonderes, mein Geschmack hat es nicht zu 100% getroffen. Aber deutlich besser als convenience Eis aus Pulver und für 1,30€ ein Preis-Tipp.', 'Rennrad', 189.00, 1830, 'Schwer', 1, '2026-03-28 20:47:24'),
(93, 168, 197, 'https://www.komoot.com/de-de/tour/2044246306/', NULL, NULL, 'Stülpnersteig', 'Anspruchsvolle Tour mit Start und Ziel am Markt in Zschopau. Nach der Tour perfekt für ein Eis!', 'Wanderung', 13.30, 390, 'Mittel', 1, '2026-04-05 06:28:48'),
(94, 81, 1, 'https://www.komoot.com/de-de/tour/2868292513/', 'adsa8nYesk48scr641VbkkwnNTztbBPFUvZ5VhxqeYBPGnEYRi', '<iframe src=\"https://www.komoot.com/de-de/tour/2868292513/embed?share_token=adsa8nYesk48scr641VbkkwnNTztbBPFUvZ5VhxqeYBPGnEYRi&amp;layout=map\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Raubrittersteig - Eiscafé Ys - Schloss Burg', 'Start und Ziel bei Schloss Burg in der Nähe von Hartenstein geht\'s über den Raubrittersteig in den Kurpark von Bad Schlema.\nZum Ostermontag sollte dort ein Ostermarkt sein und die erhoffte Eis-Einkehr.\nDanach am Silberbachstausee zurück.', 'Wanderung', 18.00, 350, 'Mittel', 1, '2026-04-06 04:38:22'),
(95, 23, 1, 'https://www.komoot.de/tour/2893438802/', 'aKx9CHjBjnPcz8eJIZBj670MVwyDNlR0gzDWmyeR2wgjBDPLW6', '<iframe src=\"https://www.komoot.com/de-de/tour/2893438802/embed?share_token=aKx9CHjBjnPcz8eJIZBj670MVwyDNlR0gzDWmyeR2wgjBDPLW6&amp;layout=map\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Lange Eis Runde gen Osten', '', 'Rennrad', 165.00, 2000, 'Schwer', 1, '2026-04-18 04:35:19'),
(96, 74, 210, 'https://www.komoot.com/de-de/tour/2896061261/', NULL, '<iframe src=\"https://www.komoot.com/de-de/tour/2893729837/embed\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Höhenmeter sind die schönsten Meter!', '', 'Rennrad', 124.00, 2000, 'Schwer', 1, '2026-04-18 15:53:54'),
(97, 700, 210, 'https://www.komoot.com/de-de/tour/2900860604/', NULL, '<iframe src=\"https://www.komoot.com/de-de/tour/2900860604/embed\" width=\"640\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Meißen - Riesa - Meißen', '', 'Rennrad', 76.00, 450, 'Leicht', 1, '2026-04-23 16:03:02'),
(98, 22, 1, 'https://www.komoot.com/de-de/tour/2924165249/', 'a1G77oi9Ah329WPClHHzgB7wN1zLlO9jWI9yzuyLQG06MdsDq1', '<iframe src=\"https://www.komoot.com/de-de/tour/2924165249/embed?share_token=a1G77oi9Ah329WPClHHzgB7wN1zLlO9jWI9yzuyLQG06MdsDq1&amp;layout=map\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Leipziger Seenrunde + 3 Eis-Stopps', 'Schöne lange, aber nicht sehr anspruchsvolle Tour (außer für den Hintern und die Kondition).\nDas schöne Frühlingswetter heute mal nutzen.', 'Rennrad', 164.00, 1350, 'Schwer', 1, '2026-05-01 07:16:52'),
(99, 852, 53, 'https://www.komoot.de/tour/3084746060/', NULL, '<iframe src=\"https://www.komoot.com/de-de/tour/3084746060/embed?layout=map\" width=\"100%\" height=\"440\" frameborder=\"0\" scrolling=\"no\"></iframe>', 'Südlich von Mailand', 'Klein Runde entlang von kleinen Kanälen und Co', 'Gravel', 21.00, NULL, 'Leicht', 1, '2026-07-04 19:20:55');
